# Token-bucket rate limiter in TypeScript

## Design notes

- **Continuous refill.** No timers or ticks. Each bucket stores `{tokens, updatedAt}`, and on every access it adds `elapsed * rate` tokens, capped at capacity.
- **Concurrency.** Node runs JS on one thread, so a synchronous read-modify-write is atomic. `tryConsume` has no `await` inside, so concurrent async callers can never interleave mid-update. The tests check this.
- **Eviction.**
  - *Lossless idle eviction.* A bucket idle for at least `capacity / rate` seconds is full again, so it is indistinguishable from a brand-new one and can be dropped without changing behavior. `idleTtlMs` defaults to that value, and values below it are rejected.
  - *Cheap sweeping.* The `Map` is kept in least-recently-used order by deleting and re-inserting a key on every access. The sweep only looks at the oldest entries and stops at the first live one, so it costs amortized O(1) per call and needs no background timer.
  - *Optional hard cap.* `maxKeys` evicts the least recently used key. This is lossy, because an evicted key restarts with a full bucket. Use it as a memory safety valve.
- **Clock.** The `Clock` interface returns milliseconds from a monotonic source. The default uses `performance.now()`. If the clock goes backwards, no tokens are minted.

## `rate-limiter.ts`

```ts
export interface Clock {
  /** Monotonic time in milliseconds. */
  now(): number;
}

export const systemClock: Clock = { now: () => performance.now() };

export interface RateLimiterOptions {
  /** Maximum tokens a bucket holds (burst size). */
  capacity: number;
  /** Tokens added per second, continuously. */
  refillPerSecond: number;
  /**
   * Evict a key after this much idle time. Must be >= the time to refill an
   * empty bucket (the default), which makes eviction lossless.
   */
  idleTtlMs?: number;
  /** Hard cap on tracked keys. Evicts LRU key when exceeded (lossy). */
  maxKeys?: number;
  clock?: Clock;
}

export interface ConsumeResult {
  allowed: boolean;
  /** Whole tokens left after this call. */
  remaining: number;
  /** 0 if allowed; otherwise ms until `cost` tokens are available (Infinity if cost > capacity). */
  retryAfterMs: number;
}

interface Bucket {
  tokens: number;
  updatedAt: number;
}

const EPS = 1e-9; // tolerance for floating-point error in refill math

export class RateLimiter<K = string> {
  private readonly capacity: number;
  private readonly ratePerMs: number;
  private readonly idleTtlMs: number;
  private readonly maxKeys: number;
  private readonly clock: Clock;

  // Insertion order == recency order (oldest first), maintained by delete+set.
  private readonly buckets = new Map<K, Bucket>();

  constructor(opts: RateLimiterOptions) {
    const { capacity, refillPerSecond } = opts;
    if (!Number.isFinite(capacity) || capacity <= 0) {
      throw new RangeError("capacity must be a positive finite number");
    }
    if (!Number.isFinite(refillPerSecond) || refillPerSecond <= 0) {
      throw new RangeError("refillPerSecond must be a positive finite number");
    }
    this.capacity = capacity;
    this.ratePerMs = refillPerSecond / 1000;

    const fullRefillMs = Math.ceil(capacity / this.ratePerMs);
    const ttl = opts.idleTtlMs ?? fullRefillMs;
    if (!(ttl >= fullRefillMs)) {
      throw new RangeError(
        `idleTtlMs must be >= ${fullRefillMs} (time to refill an empty bucket)`,
      );
    }
    this.idleTtlMs = ttl;

    const maxKeys = opts.maxKeys ?? Infinity;
    if (!(maxKeys >= 1)) throw new RangeError("maxKeys must be >= 1");
    this.maxKeys = maxKeys;

    this.clock = opts.clock ?? systemClock;
  }

  /** Number of keys currently tracked. */
  get size(): number {
    return this.buckets.size;
  }

  /**
   * Atomically try to take `cost` tokens from `key`'s bucket.
   * Fully synchronous, so concurrent async callers cannot interleave inside it.
   */
  tryConsume(key: K, cost = 1): ConsumeResult {
    if (!Number.isFinite(cost) || cost <= 0) {
      throw new RangeError("cost must be a positive finite number");
    }
    const now = this.clock.now();
    this.evictExpired(now);

    let bucket = this.buckets.get(key);
    if (bucket) {
      this.buckets.delete(key); // re-inserted below to mark as most recent
      this.refill(bucket, now);
    } else {
      while (this.buckets.size >= this.maxKeys) this.evictOldest();
      bucket = { tokens: this.capacity, updatedAt: now };
    }

    let result: ConsumeResult;
    if (cost > this.capacity) {
      result = { allowed: false, remaining: this.whole(bucket.tokens), retryAfterMs: Infinity };
    } else if (bucket.tokens + EPS >= cost) {
      bucket.tokens = Math.max(0, bucket.tokens - cost);
      result = { allowed: true, remaining: this.whole(bucket.tokens), retryAfterMs: 0 };
    } else {
      const retryAfterMs = Math.ceil((cost - bucket.tokens) / this.ratePerMs);
      result = { allowed: false, remaining: this.whole(bucket.tokens), retryAfterMs };
    }

    this.buckets.set(key, bucket);
    return result;
  }

  /** Tokens currently available (fractional). Does not consume, create, or touch recency. */
  peek(key: K): number {
    const bucket = this.buckets.get(key);
    if (!bucket) return this.capacity;
    const elapsed = Math.max(0, this.clock.now() - bucket.updatedAt);
    return Math.min(this.capacity, bucket.tokens + elapsed * this.ratePerMs);
  }

  /** Evict all expired keys now. Returns how many were removed. */
  sweep(): number {
    return this.evictExpired(this.clock.now());
  }

  /** Forget a key (it will start with a full bucket). */
  reset(key: K): boolean {
    return this.buckets.delete(key);
  }

  clear(): void {
    this.buckets.clear();
  }

  // --- internals ---------------------------------------------------------

  private refill(bucket: Bucket, now: number): void {
    // If the clock went backwards, elapsed is 0 and updatedAt never regresses,
    // so a misbehaving clock can't mint tokens.
    const elapsed = Math.max(0, now - bucket.updatedAt);
    bucket.tokens = Math.min(this.capacity, bucket.tokens + elapsed * this.ratePerMs);
    bucket.updatedAt = Math.max(bucket.updatedAt, now);
  }

  private whole(tokens: number): number {
    return Math.floor(tokens + EPS);
  }

  /** Map is in LRU order, so only the head can be the stalest; stop at first live entry. */
  private evictExpired(now: number): number {
    let removed = 0;
    for (const [key, bucket] of this.buckets) {
      if (now - bucket.updatedAt < this.idleTtlMs) break;
      this.buckets.delete(key); // deleting during Map iteration is safe
      removed++;
    }
    return removed;
  }

  private evictOldest(): void {
    const oldest = this.buckets.keys().next();
    if (!oldest.done) this.buckets.delete(oldest.value);
  }
}
